import{n as C}from"./main-F4USLEF7.js";import{En as eN,Tr as te}from"./chunk-xPHJV04V.js";var l=$localize`Coach Hajaro`;var o=(i,t)=>({type:`h2`,id:i,text:t});var b=(i,t)=>({type:`h3`,id:i,text:t});var e=i=>({type:`p`,text:i});var s=(...i)=>({type:`ul`,items:i});var d=(...i)=>({type:`ol`,items:i});var c=i=>({type:`callout`,text:i});var a=(i,t)=>({type:`link`,text:i,href:t});var y=[{id:`progressive-overload-guide`,slug:`progressive-overload-guide`,title:$localize`Progressive Overload: The Principle Behind Every Good Program`,seoTitle:$localize`Progressive Overload Explained: How to Keep Building Muscle`,metaDescription:$localize`Learn what progressive overload is, the different ways to apply it, and a simple double-progression system to keep building muscle and strength.`,excerpt:$localize`Muscles adapt to what you ask of them. Progressive overload is how you keep asking a little more. Here is how to apply it without burning out.`,category:`muscle-growth`,author:l,publishedAt:`2026-03-02`,updatedAt:`2026-09-18`,readingMinutes:7,tags:[$localize`progressive overload`,`hypertrophy`,`programming`],featured:!0,published:!0,body:[e($localize`If one principle separates training from just exercising, it is progressive overload: slowly increasing what you ask of your muscles over time, so they have a reason to keep adapting.`),o(`what-is-progressive-overload`,$localize`What progressive overload actually means`),e($localize`Your body adapts to the stress you put on it. Once a weight feels easy for the same number of reps, it is no longer a new challenge and progress slows. Overload means doing slightly more than before. Not every session, but steadily over weeks and months.`),o(`ways-to-progress`,$localize`Ways to progress`),s($localize`Weight: lifting more for the same number of reps.`,$localize`Reps: doing more reps with the same weight.`,$localize`Sets: adding sets, carefully and within what you can recover from.`,$localize`Range and control: doing the same work through a fuller range, or lowering the weight more slowly.`),c($localize`Adding weight while your technique gets worse is not progressive overload. It's a different, easier exercise done badly.`),o(`double-progression`,$localize`A simple system: double progression`),e($localize`Double progression is the simplest reliable method for most lifters. Pick a rep range, for example 8 to 12 reps.`),d($localize`Start with a weight you can lift for 8 reps with 1 to 3 reps to spare.`,$localize`Each session, try to add a rep to one or more sets.`,$localize`When every set reaches 12 reps with good form, add the smallest weight step available.`,$localize`Drop back towards 8 reps with the new weight and repeat.`),b(`track-everything`,$localize`Track everything`),e($localize`Progress you don't write down is progress you can't steer. Log your sets, reps and weights. The workout planner on this site is made for exactly that.`),a($localize`Open the workout planner`,`/workout-planner`),o(`when-progress-stalls`,$localize`When progress stalls`),e($localize`Getting stuck is normal. Before you change your program, check the basics: sleep, total calories, protein and stress. If those are fine and you've been stuck for two or three weeks, try a deload week or a small change in exercises.`),a($localize`See the training programs`,`/programs`)]},{id:`protein-intake-for-muscle-growth`,slug:`protein-intake-for-muscle-growth`,title:$localize`How Much Protein Do You Need to Build Muscle?`,seoTitle:$localize`Protein Intake for Muscle Growth: How Much Do You Need?`,metaDescription:$localize`What research says about protein for building muscle, how to spread it over the day, and practical high-protein foods.`,excerpt:$localize`Protein is what muscle is made of. Here is how much you need, how to spread it over your day and how to reach your target with normal food.`,category:`nutrition`,author:l,publishedAt:`2026-04-11`,updatedAt:`2026-08-30`,readingMinutes:6,tags:[`protein`,`nutrition`,$localize`muscle growth`],featured:!0,published:!0,body:[e($localize`Training gives your muscles a reason to grow; protein is the material they grow from. Without enough of it, your work in the gym gives you less than it could.`),o(`how-much`,$localize`How much protein per day?`),e($localize`For most people who lift and want to build muscle, research supports about 1.6 to 2.2 g of protein per kilogram of body weight per day. During a fat-loss phase, aiming for the higher end helps you keep your muscle.`),c($localize`Example: someone who weighs 80 kg would aim for about 130 to 175 g of protein a day.`),o(`distribution`,$localize`Spread it across the day`),e($localize`Eating protein over three to five meals, each with about 0.3 to 0.5 g per kg of body weight, is a practical way to reach your target and keep muscle building going through the day.`),o(`food-sources`,$localize`High-quality protein sources`),s($localize`Lean meat and poultry: chicken, turkey, lean beef`,$localize`Fish and seafood: salmon, tuna, white fish, prawns`,$localize`Eggs and dairy: Greek yoghurt, skyr, cottage cheese, milk`,$localize`Plant-based: tofu, tempeh, lentils, beans, edamame and blended plant proteins`,$localize`Protein powder: handy when normal food falls short`),o(`special-cases`,$localize`A note on health`),e($localize`If you have kidney disease or another medical condition, talk to your doctor or a registered dietitian before eating more protein.`),a($localize`Calculate your daily protein target`,`/nutrition/calculators`)]},{id:`squat-technique-guide`,slug:`squat-technique-guide`,title:$localize`Squat Technique: Squatting Safely, Step by Step`,seoTitle:$localize`How to Squat Properly: Step-by-Step Barbell Squat Technique`,metaDescription:$localize`Learn the barbell squat: step-by-step setup, cues for the movement, common mistakes and how to find the right depth for your body.`,excerpt:$localize`Done well, the squat builds more lower-body muscle and strength than almost any other exercise. Here is how to set up, perform and progress it.`,category:`exercise-technique`,author:l,publishedAt:`2026-05-06`,updatedAt:`2026-05-06`,readingMinutes:8,tags:[`squat`,`technique`,`legs`],published:!0,body:[e($localize`The barbell back squat trains your quads, glutes and adductors, and asks a lot of your core and upper back. Good technique lets you load it heavily and safely for years.`),o(`setup`,$localize`Setup`),d($localize`Set the bar at mid-chest height in a rack with safety bars just below your bottom position.`,$localize`Step under the bar and place it on your upper back, resting on the muscle, not on your neck.`,$localize`Grip the bar just outside your shoulders and pull your elbows down to tighten your upper back.`,$localize`Stand up to unrack, take two or three steps back and set your feet roughly shoulder-width apart with toes slightly turned out.`),o(`execution`,$localize`Execution`),d($localize`Take a deep breath into your belly and sides, then brace as if preparing for a punch.`,$localize`Sit down between your hips, allowing your knees to travel forward and track over your toes.`,$localize`Descend to the deepest position you can control with a neutral spine and heels on the floor.`,$localize`Drive up through your whole foot, keeping your chest up and your brace tight.`),o(`depth`,$localize`How deep should you squat?`),e($localize`Squat as deep as you can while keeping a neutral lower back and your whole foot on the floor. For most people that is at or below parallel. Deeper squats train the quads and glutes through a longer range, which helps muscle growth.`),o(`common-mistakes`,$localize`Common mistakes`),s($localize`Knees falling inwards: think about spreading the floor apart with your feet.`,$localize`Heels lifting: work on ankle mobility, or put something under your heels for now.`,$localize`Losing tension at the bottom: use less weight and practise pausing at the bottom.`,$localize`Hips shooting up first (a 'good-morning squat'): slow down and lead with your chest.`),a($localize`See the barbell back squat in the exercise library`,`/exercises/barbell-back-squat`),a($localize`See the leg muscles on the anatomy chart`,`/muscle-chart?muscle=quadriceps`)]},{id:`sustainable-fat-loss`,slug:`sustainable-fat-loss`,title:$localize`Losing Fat Without Losing Muscle`,seoTitle:$localize`How to Lose Fat Without Losing Muscle: A Practical Guide`,metaDescription:$localize`How to set a calorie deficit you can keep up, keep training heavy, eat enough protein and use cardio well, so you lose fat and keep your muscle.`,excerpt:$localize`Fat loss is simple on paper and hard in practice. These are the things that matter, and how to use them without losing muscle.`,category:`fat-loss`,author:l,publishedAt:`2026-06-14`,updatedAt:`2026-10-02`,readingMinutes:7,tags:[$localize`fat loss`,$localize`calorie deficit`,`cutting`],featured:!0,published:!0,body:[e($localize`Losing fat requires a calorie deficit: taking in less energy than you use. Keeping your muscle while you do it takes more: hard training, plenty of protein and a deficit that isn't too big.`),o(`the-deficit`,$localize`Set a moderate deficit`),e($localize`Losing about 0.5 to 1% of your body weight per week is a sensible target for most people. Going faster raises the risk of muscle loss, hunger and tiredness, and is harder to keep up.`),o(`keep-training-heavy`,$localize`Keep training heavy`),e($localize`Strength training is the signal that tells your body to keep its muscle. Keep lifting the same weights, even if you do slightly fewer sets later in the diet.`),o(`protein`,$localize`Eat enough protein`),e($localize`You need more protein in a deficit. Aiming for about 1.8 to 2.2 g per kg of body weight helps you keep your muscle and keeps you fuller between meals.`),o(`cardio`,$localize`Use cardio as a tool`),s($localize`Daily steps are an underrated way to burn more energy without getting tired.`,$localize`Easy cardio like uphill walking is easy to recover from.`,$localize`Hard intervals work, but they make you tired, so use them sparingly.`),o(`track-trends`,$localize`Watch the trend, not a single weigh-in`),e($localize`Your weight changes every day because of water, how much food is in you and salt. Weigh yourself under the same conditions and compare weekly averages, together with measurements and photos.`),c($localize`Only follow a very low-calorie diet under medical supervision.`),a($localize`Estimate your daily calorie needs`,`/nutrition/calculators`),a($localize`See the Fat Loss & Definition program`,`/programs/fat-loss-and-definition`)]},{id:`sleep-and-recovery-for-lifters`,slug:`sleep-and-recovery-for-lifters`,title:$localize`Sleep and Recovery: Where Muscle Is Built`,seoTitle:$localize`Sleep and Recovery for Muscle Growth: A Lifter’s Guide`,metaDescription:$localize`Why sleep and recovery matter for muscle growth and strength, and practical habits to recover better between training sessions.`,excerpt:$localize`Training tires your muscles out; recovery is when they come back stronger. These habits help you recover faster and train harder.`,category:`recovery`,author:l,publishedAt:`2026-07-20`,updatedAt:`2026-07-20`,readingMinutes:5,tags:[`sleep`,`recovery`,`deload`],published:!0,body:[e($localize`Training is the reason muscle grows, but the growing itself happens while you recover. Poor recovery limits how hard you can train and how well your body responds.`),o(`sleep`,$localize`Sleep comes first`),e($localize`Most adults do best with 7 to 9 hours of sleep a night. Too little sleep goes together with worse performance, more hunger and poorer recovery.`),s($localize`Go to bed and get up at the same time, weekends included.`,$localize`Make your bedroom dark, quiet and cool.`,$localize`Limit caffeine in the 8 hours before bed.`,$localize`Wind down without bright screens in the last 30 to 60 minutes.`),o(`deloads`,$localize`Plan deloads`),e($localize`A deload is a planned week with fewer sets or lighter weights. Taking one every 6 to 8 weeks, or when performance, sleep and motivation all drop, lets fatigue clear so you can keep progressing.`),o(`active-recovery`,$localize`Active recovery`),e($localize`Light walking, mobility work and easy cycling get your blood flowing without making you tired. They're ideal for rest days.`),a($localize`Learn more about nutrition and recovery`,`/nutrition`)]},{id:`creatine-evidence-guide`,slug:`creatine-evidence-guide`,title:$localize`Creatine: What the Research Says`,seoTitle:$localize`Creatine Monohydrate: Benefits, Dosage and Evidence`,metaDescription:$localize`What research says about creatine monohydrate: what it does, the usual dose, who may benefit and what it won't do.`,excerpt:$localize`Creatine is one of the most researched sports supplements. Here is what it can and can't do, without the marketing.`,category:`supplements`,author:l,publishedAt:`2026-08-08`,updatedAt:`2026-08-08`,readingMinutes:5,tags:[`creatine`,`supplements`,`evidence`],published:!0,body:[e($localize`Supplements are the smallest piece of the puzzle. Training, food and sleep come first. That said, creatine monohydrate is one of the most studied supplements in sports nutrition.`),o(`what-it-does`,$localize`What creatine does`),e($localize`Creatine fills up your muscles' stores of phosphocreatine, which helps them make energy for short, hard efforts like heavy sets. Over time this can help you train a little better, and so gain a little more muscle and strength.`),o(`dosage`,$localize`Typical dosage`),e($localize`A common intake is 3 to 5 g of creatine monohydrate a day, at any time of day. A loading phase is optional; it only fills your muscles faster.`),o(`what-it-wont-do`,$localize`What it will not do`),s($localize`It won't replace consistent training or good food.`,$localize`It does not burn fat.`,$localize`The effects are small.`),c($localize`Supplements are not medicines and are not meant to diagnose, treat, cure or prevent any disease. Talk to a healthcare professional before using supplements, especially if you have a medical condition or take medication.`),a($localize`Read the nutrition guide`,`/nutrition`)]},{id:`building-training-consistency`,slug:`building-training-consistency`,title:$localize`When Motivation Fades: How to Keep Training Anyway`,seoTitle:$localize`How to Stay Consistent With Training When Motivation Fades`,metaDescription:$localize`Practical ways to train consistently: a minimum session, planning ahead, making it easy and tracking your progress.`,excerpt:$localize`Motivation gets you started; habits keep you going. Practical ways to make training something you just do.`,category:`motivation`,author:l,publishedAt:`2026-09-25`,updatedAt:`2026-09-25`,readingMinutes:4,tags:[`motivation`,`habits`,`consistency`],published:!0,body:[e($localize`Everyone who lifts has days when they don't feel like training. The people who progress most are usually the ones who keep showing up on those days.`),o(`schedule-it`,$localize`Schedule sessions like appointments`),e($localize`Decide in advance when you'll train each week. A fixed time and place means you don't have to decide every day.`),o(`minimum-session`,$localize`Define a minimum session`),e($localize`On hard days, promise yourself only the warm-up and the first exercise. Most of the time you'll finish the workout. When you don't, you've still kept the habit going.`),o(`track-progress`,$localize`Make progress visible`),e($localize`Logging your workouts shows you how far you've come. Seeing your numbers go up keeps you going like little else does.`),o(`get-support`,$localize`Get support`),e($localize`Someone to answer to, a training partner or a coach, makes it much easier to stick with it. Knowing someone will look at your week is a good reason to show up.`),a($localize`Book a free intro`,`/contact`)]}];var m=class i extends C{published=eN(()=>this.all().filter(t=>t.published).slice().sort((t,r)=>r.publishedAt.localeCompare(t.publishedAt)));featured=eN(()=>this.published().filter(t=>t.featured));constructor(){super(`articles`,y)}bySlug(t){return this.published().find(r=>r.slug===t)}byCategory(t){return this.published().filter(r=>r.category===t)}related(t,r=3){let h=this.published().filter(n=>n.id!==t.id),w=h.filter(n=>n.category===t.category),f=h.filter(n=>n.category!==t.category);return[...w,...f].slice(0,r)}static ɵfac=function(r){return new(r||i)};static ɵprov=te({token:i,factory:i.ɵfac,providedIn:`root`})};export{m as t};